const frame = msg.payload || msg;
let canId = frame.canid & 0x1FFFFFFF;
const data = frame.data || [];

let state = flow.get("pcsPowerState") || {
    kind: "PcsPowerState",
    version: 1,
    // PCS_PWR_ACT (0x66B96Ax)
    pcs_aActPwrKw: null,
    pcs_bActPwrKw: null,
    pcs_cActPwrKw: null,
    pcs_outActPwrKw: null,
    // PCS_PWR_APP (0x66B96Cx)
    pcs_aAppPwrKva: null,
    pcs_bAppPwrKva: null,
    pcs_cAppPwrKva: null,
    pcs_outAppPwrKva: null,
    // PCS_PWR_REA (0x66B96Bx)
    pcs_aReaPwrKvar: null,
    pcs_bReaPwrKvar: null,
    pcs_cReaPwrKvar: null,
    pcs_outReaPwrKvar: null
};

// Helper function
function s16(buf, offset) {
    let val = (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
    return val > 32767 ? val - 65536 : val;
}

var processed = false;

// ==================== PCS_PWR_ACT (0x66B96Ax) ====================
if ((canId & 0xFFFFFFF0) === 0x66B96A0) {
    processed = true;

    // Bit 0-15: A Phase Active Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kW
    // Min: -3276.8, Max: 3276.7
    state.pcs_aActPwrKw = s16(data, 0) * 0.1;

    // Bit 16-31: B Phase Active Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kW
    // Min: -3276.8, Max: 3276.7
    state.pcs_bActPwrKw = s16(data, 2) * 0.1;

    // Bit 32-47: C Phase Active Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kW
    // Min: -3276.8, Max: 3276.7
    state.pcs_cActPwrKw = s16(data, 4) * 0.1;

    // Bit 48-63: Output Active Power (Total)
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kW
    // Min: -3276.8, Max: 3276.7
    state.pcs_outActPwrKw = s16(data, 6) * 0.1;
}

// ==================== PCS_PWR_REA (0x66B96Bx) ====================
if ((canId & 0xFFFFFFF0) === 0x66B96B0) {
    processed = true;

    // Bit 0-15: A Phase Reactive Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kvar
    // Min: -3276.8, Max: 3276.7
    state.pcs_aReaPwrKvar = s16(data, 0) * 0.1;

    // Bit 16-31: B Phase Reactive Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kvar
    // Min: -3276.8, Max: 3276.7
    state.pcs_bReaPwrKvar = s16(data, 2) * 0.1;

    // Bit 32-47: C Phase Reactive Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kvar
    // Min: -3276.8, Max: 3276.7
    state.pcs_cReaPwrKvar = s16(data, 4) * 0.1;

    // Bit 48-63: Output Reactive Power (Total)
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kvar
    // Min: -3276.8, Max: 3276.7
    state.pcs_outReaPwrKvar = s16(data, 6) * 0.1;
}

// ==================== PCS_PWR_APP (0x66B96Cx) ====================
if ((canId & 0xFFFFFFF0) === 0x66B96C0) {
    processed = true;

    // Bit 0-15: A Phase Apparent Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kVA
    // Min: 0, Max: 6553.5
    state.pcs_aAppPwrKva = s16(data, 0) * 0.1;

    // Bit 16-31: B Phase Apparent Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kVA
    // Min: 0, Max: 6553.5
    state.pcs_bAppPwrKva = s16(data, 2) * 0.1;

    // Bit 32-47: C Phase Apparent Power
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kVA
    // Min: 0, Max: 6553.5
    state.pcs_cAppPwrKva = s16(data, 4) * 0.1;

    // Bit 48-63: Output Apparent Power (Total)
    // 16 bit, Signed, Factor: 0.1, Offset: 0, Unit: kVA
    // Min: 0, Max: 6553.5
    state.pcs_outAppPwrKva = s16(data, 6) * 0.1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("pcsPowerState", state);
msg.payload = state;
return msg;

var state = flow.get("pcsPowerState");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
